using Npgsql;using SistemaPrestamos.Api.Services;var cs=Environment.GetEnvironmentVariable("PROBE_CONNECTION")??throw new Exception("Missing connection");await using var source=NpgsqlDataSource.Create(cs);var passwords=new PasswordService();var repo=new UsuarioRepository(source,passwords);int testId=0;var admin=(await repo.ListAsync()).Single(x=>x.Rol=="ADMIN"&&x.Estado=="ACTIVO");try{testId=await repo.CreateAsync(new("Usuario temporal","codex_permiso_test","ClaveTemporal123!","COBRADOR"),admin.Id);await repo.ResetPasswordAsync(testId,"NuevaClaveTemporal123!",admin.Id);await repo.UpdateAsync(testId,new("Usuario temporal","CONSULTA","INACTIVO"),admin.Id);var protectedAdmin=false;try{await repo.UpdateAsync(admin.Id,new(admin.Nombre,"CONSULTA","ACTIVO"),admin.Id);}catch(ArgumentException){protectedAdmin=true;}if(!protectedAdmin)throw new Exception("No se protegió el último administrador");Console.WriteLine("USUARIOS_OK CREAR=SI CLAVE=SI CAMBIO_ROL=SI ULTIMO_ADMIN_PROTEGIDO=SI");}finally{if(testId>0){await using(var a=source.CreateCommand("DELETE FROM prestamos.auditoria_usuarios WHERE id_usuario=$1")){a.Parameters.AddWithValue(testId);await a.ExecuteNonQueryAsync();}await using var u=source.CreateCommand("DELETE FROM prestamos.usuarios WHERE id_usuario=$1");u.Parameters.AddWithValue(testId);await u.ExecuteNonQueryAsync();}}
